try {
  const data = JSON.parse($input.first().json.stdout);
  return[{ json: data }];
} catch (e) {
  return[{ json: { Transcript: "" } }];
}

const items = $input.all();
let fullTranscript = "";

if (items && items.length > 0 && items[0].json) {
  const data = items[0].json;

  // 1. Buscar en los nombres más comunes que usa Apify
  if (data.text && typeof data.text === 'string') {
    fullTranscript = data.text;
  } else if (data.transcript_text && typeof data.transcript_text === 'string') {
    fullTranscript = data.transcript_text;
  } else if (data.transcript && typeof data.transcript === 'string') {
    fullTranscript = data.transcript;
  } 
  // 2. Por si Apify lo devuelve como una lista fragmentada de oraciones
  else if (Array.isArray(data.transcript)) {
    fullTranscript = data.transcript.map(t => t.text || t).join(' ');
  } else if (Array.isArray(data.subtitles)) {
    fullTranscript = data.subtitles.map(t => t.text || t).join(' ');
  } 
  // 3. Modo Bestia: Si todo falla, buscar el texto más largo de todo el JSON
  else {
    let longestString = "";
    for (const key in data) {
      if (typeof data[key] === 'string' && data[key].length > longestString.length) {
        longestString = data[key];
      }
    }
    // Si el texto tiene más de 200 caracteres, asumimos que es el guion
    if (longestString.length > 200) { 
        fullTranscript = longestString;
    }
  }
}

return [{ json: { Transcript: fullTranscript } }];

let text = $input.first().json.text || $input.first().json.output || '';

// Extraer sólo la parte que parece un JSON
let jsonStr = text;
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (jsonMatch) {
    jsonStr = jsonMatch[0];
}

try {
  const data = JSON.parse(jsonStr);
  return [{ json: { output: data } }];
} catch (error) {
  throw new Error("No se pudo extraer el JSON del empaque. Respuesta de la IA: " + text);
}

let output = $input.first().json.text || $input.first().json.output || $input.first().json.message?.content || '';

let scriptLimpio = output;

// Extraer desde STRUCTURED STORY
if (output.includes('[STRUCTURED STORY]')) {
    scriptLimpio = output.split('[STRUCTURED STORY]')[1];
} else if (output.includes('STRUCTURED STORY')) {
    scriptLimpio = output.split('STRUCTURED STORY')[1];
}

// Cortar la basura de los metadatos del final SOLO para el guion limpio
if (scriptLimpio.includes('[CONTENT DNA]')) {
    scriptLimpio = scriptLimpio.split('[CONTENT DNA]')[0];
}

// Limpiar espacios y caracteres extra
scriptLimpio = scriptLimpio.replace(/^[\:\*\-\s]+/, '').trim();

return [{ 
  json: { 
    Script: output, // Pasamos el texto COMPLETO (con tags) para el nodo de empaque
    ScriptLimpio: scriptLimpio // Guardamos el guion limpio para crear el .txt más adelante
  } 
}];

const data = $input.first().json.output || {};
let packaging = data.packaging || data;

let prompts = packaging.scene_prompts || packaging.escenas_visuales || packaging.escenas || [];
if (prompts.length === 0) {
  for (const key in packaging) {
    if (Array.isArray(packaging[key]) && key !== 'etiquetas' && key !== 'nombres_capitulos') {
      if (packaging[key].length > prompts.length) {
         prompts = packaging[key];
      }
    }
  }
}

const safeGetStr = (obj, key, fallback = 'No generado') => obj && obj[key] ? obj[key] : fallback;
const safeGetArr = (obj, key) => obj && Array.isArray(obj[key]) ? obj[key] : [];

const etiquetas = safeGetArr(packaging, 'etiquetas');
const hashtags = etiquetas.slice(0, 5).map(tag => '#' + tag.replace(/\s+/g, '')).join(' ');

let video_rec = safeGetStr(packaging, 'video_recomendado', 'Ninguno');
if (video_rec === 'Ninguno' || video_rec === 'None' || video_rec === 'No generado') {
    video_rec = '(Sin video recomendado)';
}

// 1. Procesar Títulos
const titulos = safeGetArr(packaging, 'titulos_sugeridos');
let titulosTexto = "";
if (titulos.length > 0) {
  titulosTexto = titulos.map((t, i) => `${i + 1}. ${t}`).join('\n');
} else {
  // Por si la IA falla y manda el título en el formato antiguo
  titulosTexto = safeGetStr(packaging, 'titulo', 'Título no generado');
}

//Rescatar el título ganador (si falla, toma el primero de la lista por seguridad)
let tituloGanador = safeGetStr(packaging, 'titulo_ganador', titulos[0] || 'No generado');

// 2. Archivo PACKAGING REORDENADO
let content = `TÍTULOS SUGERIDOS:\n${titulosTexto}\n\n`;
content += `TÍTULO GANADOR (Elegido por IA): ${tituloGanador}\n\n`;
content += `DESCRIPCIÓN:\n${safeGetStr(packaging, 'descripcion')}\n\n${hashtags}\n\n`;
content += `ETIQUETAS: ${etiquetas.length > 0 ? etiquetas.join(', ') : 'No generadas'}\n\n`;
content += `VIDEO RECOMENDADO: ${video_rec}\n\n`;
content += `PLAYLIST SUGERIDA: ${packaging.playlist_sugerida || packaging.suggested_playlist || 'Revisar manualmente'}\n\n`;

// 3. Archivo PROMPTS
let promptsContent = "";
let thumbPrompt = safeGetStr(packaging, 'concepto_visual', '');
if (thumbPrompt !== 'No generado') promptsContent += thumbPrompt.trim() + "\n\n";

if (Array.isArray(prompts) && prompts.length > 0) {
  prompts.forEach((p) => {
    let promptText = typeof p === 'string' ? p : (p.prompt || p.descripcion || p.image_prompt || JSON.stringify(p));
    promptsContent += promptText.trim() + "\n\n";
  });
} else {
  promptsContent += "No se encontraron descripciones de escenas.\n";
}

const jsonSalida = $input.first().json;
// Inyectamos el título ganador seguro en el JSON para que NocoDB lo pueda leer
jsonSalida.titulo_ganador_seguro = tituloGanador;

return [{
  json: jsonSalida,
  binary: {
    data: {
      data: Buffer.from(content.trim(), 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'packaging.txt'
    },
    prompts_bin: {
      data: Buffer.from(promptsContent.trim(), 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: 'prompts_imágenes.txt'
    }
  }
}];

function sluggify(str) {
  if (!str) return 'proyecto-sin-titulo';
  str = str.toLowerCase().trim();
  str = str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  str = str.replace(/[^\w\s-]/g, '').replace(/[\s_]+/g, '-').replace(/^-+|-+$/g, '');
  return str;
}

// Rescatamos el título original extraído al principio
const tituloYoutube = $('Obtener Info Video YT').first().json.title;
const data = $input.first().json;

let transcriptFinal = "";

// Intentamos sacar el texto de Python
try {
  transcriptFinal = $('Verificar Python').first().json.Transcript;
} catch (error) { }

// Si no hay texto, intentamos sacarlo de Apify
if (!transcriptFinal) {
  try {
    transcriptFinal = $('Verificar Apify').first().json.Transcript;
  } catch (error) { }
}

// AQUÍ ESTÁ EL TRUCO DE LA NUMERACIÓN
// Rescatamos el ID numérico de tu base de datos
let idVideo = "0";
try {
  idVideo = $('Seleccionar Primer Video').first().json.Id;
} catch(e) { }

// Generamos el texto limpio y le pegamos el número al inicio
const slugBase = sluggify(tituloYoutube);
data.sluggified = `${idVideo}-${slugBase}`; // Quedará como "15-el-titulo-del-video"

// Guardamos la transcripción y reconstruimos la metadata esencial
data.Transcript = transcriptFinal || "";
data.title = tituloYoutube;

// Rescatar URL del primer nodo
try {
  data['Source Video URL'] = $('Seleccionar Primer Video').first().json['Source Video URL'];
} catch(e) { }

return [{ json: data }];

// 1. Tomar la respuesta cruda del LLM
const jsonOriginal = $input.first().json;
let text = jsonOriginal.text || jsonOriginal.output || '';

// 2. Extraer el JSON limpio
let jsonStr = text;
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (jsonMatch) {
    jsonStr = jsonMatch[0];
}

let es_valido = false;
try {
  const parsed = JSON.parse(jsonStr);
  es_valido = parsed.es_valido_para_animacion_2d === true || parsed.es_valido_para_animacion_2d === "true";
} catch (error) {
  es_valido = false; // Ante la duda, descartar
}

// 3. ¡EL TRUCO MAESTRO! Recuperamos todos los datos (Slug, URL, Guion)
// que el nodo de LangChain eliminó.
const datosCompletos = $('Generar Slug Proyecto').first().json;

// 4. Le inyectamos el veredicto
datosCompletos.es_valido = es_valido;

return [{ json: datosCompletos }];

const allVideos = $input.all().map(item => item.json);

// Filtrar solo los videos que están listos, eliminamos la regla del check
const disponibles = allVideos.filter(v => v.Status === 'Hecho');

// Ordenar del más nuevo al más viejo asumiendo que un Id mayor es más reciente
disponibles.sort((a, b) => b.Id - a.Id);

// Tomar los 15 más recientes
const recientes = disponibles.slice(0, 15);

// Mezclar esos 15 para que la IA no reciba siempre el mismo orden exacto
for (let i = recientes.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [recientes[i], recientes[j]] = [recientes[j], recientes[i]];
}

// Extraer los títulos en texto plano
let titulos_texto = "No hay videos disponibles";
if (recientes.length > 0) {
  titulos_texto = recientes.map(v => "- " + (v["Nuevo Titulo"] || v["Titulo Original"] || v.title)).join('\n');
}

return [{
  json: {
    seleccionados: recientes,
    titulos_texto: titulos_texto
  }
}];

let script = "";
try {
  // AQUÍ ESTÁ EL CAMBIO CLAVE: Jalamos ScriptLimpio para que el TXT no tenga basura
  script = $('Extraer Texto Guion').first().json.ScriptLimpio || '';
} catch(error) {
  script = "Error: No se pudo encontrar el texto del guion en el nodo 'Extraer Texto Guion'.";
}

script = script.replace(/\\n/g, '\n').replace(/(?:\r\n|\r|\n)/g, '\r\n');
const buffer = Buffer.from(script, 'utf8');

return[{
  json: $input.first().json,
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/plain',
      fileName: 'script.txt'
    }
  }
}];
